class Solution {
    public int kthGrammar(int n, int k) {
        return Integer.bitCount(k - 1) % 2;
    }
}

var kthGrammar = function(n, k) {
    let count = 0;
    let x = k - 1;
    while (x > 0) {
        count += (x & 1);
        x >>= 1;
    }
    return count % 2;
};
